function solution(text: string, pattern: string): number[] {
  // result array to store the starting indices of pattern occurrences in the text
  const result: number[] = [];
  // length of the text string
  const n = text.length;
  // length of the pattern string
  const m = pattern.length;

  // If the pattern is an empty string, return all possible starting indices in the text
  if (pattern === "") {
    for (let i = 0; i < n; i++) result.push(i);
    return result;
  }

  // If the text is empty or the pattern is longer than the text, no match is possible, so return an empty array.
  if (n === 0 || m > n) return [];

  // lps array stores the longest proper prefix which is also a suffix for each sub-pattern
  const lps: number[] = new Array(m).fill(0);

  // len: length of the previous longest prefix suffix
  let len = 0;
  // i: index to traverse the pattern string
  let i = 1;

  // Compute the lps array (longest prefix suffix) for the pattern
  while (i < m) {
    // If the current character of the pattern matches the character at len, increment len and update lps[i]
    if (pattern[i] === pattern[len]) {
      len++;
      lps[i] = len;
      i++;
    } else {
      // If the current character does not match
      if (len !== 0) {
        // If len is not 0, set len to the value in lps[len - 1]
        len = lps[len - 1];
        // Note that we do not increment i here
      } else {
        // If len is 0, set lps[i] to 0 and increment i
        lps[i] = 0;
        i++;
      }
    }
  }

  // j: index for pattern string
  let j = 0;
  // i: index for text string
  i = 0;

  // Search for the pattern in the text
  while (i < n) {
    // If the current characters match, increment both i and j
    if (text[i] === pattern[j]) {
      i++;
      j++;
    }

    // If j reaches the length of the pattern, a match is found
    if (j === m) {
      // Add the starting index of the match to the result array
      result.push(i - j);
      // Update j to lps[j - 1] to find the next possible match
      j = lps[j - 1];
    } else if (i < n && text[i] !== pattern[j]) {
      // If characters do not match
      if (j !== 0) {
        // If j is not 0, set j to lps[j - 1]
        j = lps[j - 1];
      } else {
        // If j is 0, increment i
        i++;
      }
    }
  }

  // Return the result array containing the starting indices of all matches
  return result;
}
