function longestPalindromeManachers(s: string): number {
  if (s.length === 0) return 0;

  // Preprocess the string by inserting '#' between each character and at the start and end.
  // This transforms the string to handle both even and odd length palindromes uniformly.
  const processed = "#" + s.split("").join("#") + "#";
  const n = processed.length;

  // radius[i] stores the radius of the longest palindrome centered at processed[i].
  const radius = new Array(n).fill(0);

  // center: Center of the rightmost palindrome found so far.
  // right: Right boundary of the rightmost palindrome found so far.
  let center = 0;
  let right = 0;
  let maxLen = 0;

  // Iterate through the processed string.
  for (let i = 0; i < n; i++) {

    // mirror: The mirror index of i with respect to the center.
    const mirror = 2 * center - i;

    // If i is within the right boundary of the current rightmost palindrome,
    // we can initialize radius[i] using the symmetry.
    if (i < right) {
      radius[i] = Math.min(right - i, radius[mirror]);
    }

    // Attempt to expand the palindrome centered at i.
    while (
      i - radius[i] - 1 >= 0 &&
      i + radius[i] + 1 < n &&
      processed[i - radius[i] - 1] === processed[i + radius[i] + 1]
    ) {
      radius[i]++;
    }

    // If the palindrome centered at i expands past the right boundary,
    // update the center and right boundary.
    if (i + radius[i] > right) {
      center = i;
      right = i + radius[i];
    }

    // Update the maximum palindrome length found so far.
    maxLen = Math.max(maxLen, radius[i]);
  }

  // The maximum radius is the length of the longest palindrome in the original string.
  return maxLen;
}
