        // The processed string will have '#' inserted between each character of the original string,
        // and at the beginning and end. This helps handle both even and odd length palindromes uniformly.
        StringBuilder processed = new StringBuilder("#");
        // Iterate through each character of the original string.
        for (char c : s.toCharArray()) {
            // Append the character followed by '#' to the processed string.
            processed.append(c).append("#");
        }

        // Get the length of the processed string.
        int n = processed.length();
        // Create an array to store the radius of the longest palindrome centered at each index.
        int[] radius = new int[n];

