  union_operations: number[][],
  find_operations: number[],
  n: number
): number[] {

  // Initialize the parent array. parent[i] represents the parent of node i.
  const parent: number[] = new Array(n);
  // Initialize the rank array. rank[i] represents the rank (upper bound on the height) of the tree rooted at node i.
  const rank: number[] = new Array(n).fill(0);

  // Initialize parent array: Each node is initially its own parent (representing individual sets).
  for (let i = 0; i < n; i++) {
    parent[i] = i;
  }

  // find(i): Finds the root/representative of the set that element i belongs to,
  // with path compression for optimization.
  function find(i: number): number {
    // If the node is its own parent, it is the root of the set.
    if (parent[i] === i) {
      return i;
    }
    // Path compression: Recursively find the root and update the parent of the current node to point directly to the root.
    parent[i] = find(parent[i]); // path compression
    return parent[i];
  }

  // union(x, y): Merges the sets containing elements x and y using union by rank.
  function union(x: number, y: number): void {
    // Find the roots/representatives of the sets containing x and y.
    const rootX = find(x);
    const rootY = find(y);

    // If x and y are already in the same set, do nothing.
    if (rootX !== rootY) {
      // Attach the tree with the smaller rank to the tree with the larger rank.
      if (rank[rootX] < rank[rootY]) {
        parent[rootX] = rootY;
      } else if (rank[rootX] > rank[rootY]) {
        parent[rootY] = rootX;
      } else {
        // If the ranks are equal, attach one tree to the other and increment the rank of the new root.
        parent[rootY] = rootX;
        rank[rootX]++;
      }
    }
  }

  // Perform union operations.
  for (const operation of union_operations) {
    union(operation[0], operation[1]);
  }

  // Perform find operations and store the results.
  const results: number[] = [];

  for (const node of find_operations) {
    results.push(find(node));
  }

  return results;
}

