  const depth: number[] = Array(n).fill(0); // depth[i] stores the depth of node i from the root.

  // DFS function to precompute the 'up' table and 'depth' array.
  function dfs(node: number, parent: number) {
    up[node][0] = parent; // The immediate parent (2^0-th ancestor) of the node.

    // Iterate through powers of 2 to compute the 2^j-th ancestor.
    for (let j = 1; j < LOG; j++) {
