      // 2^(j-1)-th ancestor of the 2^(j-1)-th ancestor.
      if (up[node][j - 1] !== -1) {
        up[node][j] = up[up[node][j - 1]][j - 1];
      }
    }

    // Recursively call DFS for all children of the current node.
