class LRUCache {
  private capacity: number;
  private cache: Map<number, DLLNode>;
  private head: DLLNode | null;
  private tail: DLLNode | null;

  constructor(capacity: number) {
    // Initialize the capacity of the cache
    this.capacity = capacity;
    // Initialize the cache using a Map (hash map) for O(1) access
    this.cache = new Map();
    // Initialize the head of the doubly linked list to null
    this.head = null;
    // Initialize the tail of the doubly linked list to null
    this.tail = null;
  }

  get(key: number): number {
    // If the key doesn't exist in the cache, return -1
    if (!this.cache.has(key)) return -1;

    // Get the node from the cache
    const node = this.cache.get(key)!;
    // Move the accessed node to the head of the list (most recently used)
    this.moveToHead(node);
    // Return the value of the node
    return node.value;
  }

  put(key: number, value: number): void {
    // If the key already exists in the cache
    if (this.cache.has(key)) {
      // Get the existing node
      const node = this.cache.get(key)!;
      // Update the value of the node
      node.value = value;
      // Move the node to the head of the list
      this.moveToHead(node);
    } else {
      // If the key doesn't exist, create a new node
      const newNode = { key, value, prev: null, next: null };
      // Add the new node to the cache
      this.cache.set(key, newNode);
      // Add the new node to the head of the linked list
      this.addToHead(newNode);

      // If the cache size exceeds the capacity
      if (this.cache.size > this.capacity) {
        // Remove the tail node (least recently used)
        const removed = this.removeTail();
        // Remove the corresponding key from the cache
        this.cache.delete(removed.key);
      }
    }
  }

  private moveToHead(node: DLLNode): void {
    // Remove the node from its current position
    this.removeNode(node);
    // Add the node to the head of the list
    this.addToHead(node);
  }

  private removeNode(node: DLLNode): void {
    // Update the next pointer of the previous node
    if (node.prev) node.prev.next = node.next;
    // Update the previous pointer of the next node
    if (node.next) node.next.prev = node.prev;
    // If the node is the head, update the head
