  public int[] topologicalSort(Map<Integer, List<Integer>> graph) {
    int numNodes = graph.size();
    int[] indegrees = new int[numNodes];

    // Calculate in-degrees for each node.
    for (int node : graph.keySet()) {
      for (int neighbor : graph.get(node) != null ? graph.get(node) : new ArrayList<>()) {
        indegrees[neighbor]++;
      }
    }

    // Queue for nodes with in-degree of 0 (starting nodes).
    Queue<Integer> queue = new LinkedList<>();

    // Add all nodes with in-degree 0 to the queue.
    for (int i = 0; i < numNodes; i++) {
      if (indegrees[i] == 0) {
        queue.offer(i);
      }
    }

    // Result array to store the topological order.
    int[] result = new int[numNodes];
    int index = 0;

    // Process nodes from the queue.
    while (!queue.isEmpty()) {
      // Dequeue a node.
      int node = queue.poll();

      // Add the node to the result.
      result[index++] = node;

      // Iterate through the neighbors of the node.
      if (graph.containsKey(node)) {
        for (int neighbor : graph.get(node)) {
          // Reduce the in-degree of the neighbor.
          indegrees[neighbor]--;

          // If the neighbor's in-degree becomes 0, add it to the queue.
          if (indegrees[neighbor] == 0) {
            queue.offer(neighbor);
          }
        }
      }
    }

    // Check for cycles: if the result size is not equal to the graph size, there is a cycle.
    if (index != numNodes) {
      return new int[0]; // Return an empty array to indicate a cycle.
    }

    // Return the topological order.
    return result;
  }
