  // Initialize the right pointer (sell day) to the second day (index 1).
  let r = 1;

  // Initialize the maximum profit to 0. This variable will store the highest profit we can achieve.
  let maxProfit = 0;

  // Iterate through the 'prices' array using the right pointer 'r'.
  // The loop continues as long as the right pointer is within the bounds of the array.
  while (r < prices.length) {
    // Check if the current selling price (prices[r]) is greater than the current buying price (prices[l]).
    if (prices[l] < prices[r]) {
      // If it is, calculate the profit by subtracting the buying price from the selling price.
      // Update 'maxProfit' to be the maximum of the current 'maxProfit' and the calculated profit.
      maxProfit = Math.max(maxProfit, prices[r] - prices[l]);
    } else {
      // If the selling price is not greater than the buying price, it means we've found a potentially lower buying price.
      // Move the left pointer 'l' to the current position of the right pointer 'r',
      // because we want to buy at the lowest possible price.
      l = r;
    }

    // Move the right pointer 'r' to the next day to check the next potential selling price.
    r++;
  }

  // After iterating through the entire array, return the maximum profit found.
  return maxProfit;
}

