public static class Solution {
    public boolean containsDuplicate(int[] nums) {
        // Set to store unique numbers.  Using a HashSet for O(1) average time complexity for add and contains operations.
        Set<Integer> seen = new HashSet<>();

        // Iterate through the array.  We check each number in the input array 'nums'.
        for (int num : nums) {
            // If number already exists in the 'seen' set, a duplicate is found.
            // The 'contains' method of HashSet checks if the element is already present.
            if (seen.contains(num)) {
                return true; // Immediately return true if a duplicate is found.
            }

            // Add the current number to the 'seen' set.  This ensures we track encountered numbers.
            seen.add(num);
        }

        // No duplicates were found after iterating through the entire array.  Return false.
        return false;
    }
}

