            if (seen.count(num)) {
                // If the number is already in the set, it means we have found a duplicate.
                return true; // Return true immediately, indicating that a duplicate exists.
            }

            // If the number is not in the set, insert it into the set.
            // This marks the number as seen, so we can detect duplicates in future iterations.
            seen.insert(num);
        }

