function containsDuplicate(nums: number[]): boolean {
    // Use a Set data structure to efficiently store and check for the presence of each number.
    // Sets only allow unique values, making duplicate detection straightforward.
    const seen = new Set<number>();

    // Iterate through each number in the input array 'nums'.
    for (const num of nums) {
        // Check if the current number 'num' is already present in the 'seen' Set.
        // The 'has' method of a Set returns true if the element is present, and false otherwise.
        if (seen.has(num)) {
            // If the number is already in the Set, it means we have found a duplicate.
            // Immediately return true to indicate the presence of duplicates.
            return true;
        }

        // If the number is not already in the Set, add it to the Set.
        // This marks the number as 'seen' so that we can detect duplicates in subsequent iterations.
        seen.add(num);
    }

    // If the loop completes without finding any duplicates (i.e., the function hasn't returned true),
    // it means all numbers in the array are unique.
    // Return false to indicate that no duplicates were found.
    return false;
}

